       The first group cannot have a line feed inserted,
       the next one can, etc.
    """
    groups = []
    group = []
    for i, c in enumerate(line):
        if c == begin_delim:
            if group:
                groups.append(group)
                group = []
        elif c == end_delim:
            group.append(c)
            groups.append(group)
            group = []
        else:
            group.append(c)
    if group:
