        """Move an entry to another group.

        A v1Group group and a v1Entry entry are needed.

        """
        if entry is None:
            raise ValueError("No entry given.")
        if group is None:
            raise ValueError("No group given.")
        if not isinstance(entry, v1Entry):
            raise TypeError("entry is not a v1Entry.")
        if not isinstance(group, v1Group):
            raise TypeError("group is not a v1Group.")
        if entry.group != self:
            raise ValueError("entry is not in this group.")
        if group.vault != self.vault:
            raise ValueError("group is not in the same vault.")
        if group.id == self.id:
            raise ValueError("group is the same as this group.")
        if entry.id in group.entries:
            raise ValueError("entry is already in group.")
        if entry.id in self.entries:
            self.entries.remove(entry.id)
        group.entries.append(entry.id)
        self.vault.db.execute("UPDATE v1_entry SET group_id = ? WHERE id = ?", (group.id, entry.id))
        self.vault.db.commit()

