def _flushContour(self):
        """
        This normalizes the contour so that:
        - there are no line segments. in their place will be
          curve segments with the off curves positioned on top
          of the previous on curve and the new curve on curve.
        - the contour starts with an on curve
        """
        if len(self.contour) == 0:
            return
        if self.contour[0].type == "offcurve":
            self.contour[0].type = "line"
        for i in range(len(self.contour) - 1):
            if self.contour[i].type == "offcurve":
                self.contour[i].type = "line"
                self.contour[i + 1].type = "offcurve"
                self.contour[i + 1].point = self.contour[i].point
        if self.contour[-1].type == "offcurve":
            self.contour[-1].type = "line"

